const
double
&sorted[],
const
int
offset,
const
int
n,
const
double
p)
  {
//--- linear-interpolation percentile (same convention as numpy's default) so the IQR
//--- used for normalization matches what the Python validation script computes
double
rank = p*(n-
1
);
int
lo   = (
int
)
MathFloor
(rank);
int
hi   = (
int
)
MathCeil
(rank);
if
(lo==hi)
return
(sorted[offset+lo]);
double
frac = rank-lo;
return
(sorted[offset+lo]*(
1.0
-frac) + sorted[offset+hi]*frac);
  }
PercentileFromSorted() is used only to compute the reference IQR with the same interpolation convention as NumPy, ensuring offline and in-terminal consistency.
