//| CDriftDetector::PushLiveSample                                   |
//+------------------------------------------------------------------+
void
CDriftDetector::
PushLiveSample
(
const
double
&features[])
  {
for
(
int
f=
0
; f<m_num_features; f++)
      m_live_buf[f*m_live_size + m_live_head] = features[f];
//--- classic ring-buffer advance: wrap the write head and cap the fill count at
//--- m_live_size so IsLiveWindowFull() flips true exactly once the window is dense
m_live_head = (m_live_head+
1
) % m_live_size;
if
(m_live_count < m_live_size) m_live_count++;
  }
Bootstrapping the live window at startup avoids a long warm-up period before the first score becomes available.
