void
CDriftDetector::
ComputeDriftScores
(
double
&per_feature_w1[],
double
&per_feature_normalized[])
  {
ArrayResize
(per_feature_w1,m_num_features);
ArrayResize
(per_feature_normalized,m_num_features);
double
live_slice[];
ArrayResize
(live_slice,m_num_features*m_live_size);
//--- copy the circular buffer out in plain chronological-irrelevant order - Wasserstein-1
//--- is a distribution distance, so sample ORDER inside the window does not matter, only
//--- the set of values does; this lets us skip unwinding the ring buffer's wrap point
for
(
int
f=
0
; f<m_num_features; f++)
for
(
int
i=
0
;i<m_live_size;i++)
         live_slice[f*m_live_size+i] = m_live_buf[f*m_live_size+i];
for
(
int
f=
0
; f<m_num_features; f++)
     {
SortSlice
(live_slice,f*m_live_size,m_live_size);
double
w1 =
Wasserstein1D
(m_ref_sorted,f*m_ref_size,live_slice,f*m_live_size,m_live_size);
      per_feature_w1[f] = w1;
//--- normalize by the reference IQR so features with very different natural scales
//--- (a log-return near zero vs. a volume z-score in the tens) contribute comparably
//--- to the composite score instead of the largest-magnitude feature dominating it
double
iqr = m_ref_iqr[f];
if
(iqr <=
0.0
) iqr = 1e-
8
;
// degenerate reference (constant feature) - avoid /0
per_feature_normalized[f] = w1 / iqr;
     }
  }
//+------------------------------------------------------------------+
//| CDriftDetector::ComputeComposite                                 |
//+------------------------------------------------------------------+
double
CDriftDetector::
ComputeComposite
(
const
double
&normalized[],
const
double
&weights[],
double
&max_stat)
  {
double
weighted_sum =
0.0
, weight_total =
0.0
;
   max_stat =
0.0
;
for
(
int
f=
0
; f<m_num_features; f++)
     {
      weighted_sum += weights[f]*normalized[f];
      weight_total += weights[f];
//--- track the single worst-drifting feature separately from the blended average -
//--- a weighted mean can stay below threshold even while one feature has fully
//--- decoupled from its reference distribution, which the max-statistic catches
if
(normalized[f] > max_stat) max_stat = normalized[f];
     }
if
(weight_total <=
0.0
) weight_total =
1.0
;
return
(weighted_sum/weight_total);
  }
To show this is not just a nice formula that happens to work on a whiteboard, the Python companion script synthetic_shift_validation.py runs the same computation offline against three synthetic shift types — a mean shift, a variance shift, and a bimodal mixture shift constructed to leave the mean and variance almost unchanged — and compares detection rates against a naive mean/std detector, with both thresholds calibrated to roughly the same 5% false-positive rate on unshifted data.
Wasserstein-1 vs. Naive Mean/Std Detection Rate
Fig. 2. Detection rate at a matched ~5% false-positive rate. On an actual run of this script: mean shift 100% vs 100%, variance shift 100% vs 20%, bimodal mixture 100% vs 1%. The naive detector is nearly blind to a shift that changes shape without moving the mean.
That last column is the entire argument for this article in one number. A mean/std monitor caught the bimodal mixture shift on 1 out of 100 trials. The Wasserstein-1 detector caught it on all 100.
Composite Drift Score Timeline
Fig. 3. A synthetic composite-score timeline: quiet noise around the reference level, then a regime break ramps the score through the warning band and into the critical band, where HandleDriftAction fires.
