//| ExtractJsonNumber                                                |
//+------------------------------------------------------------------+
double
ExtractJsonNumber
(
const
string
&text,
const
string
key,
const
double
default_value)
  {
string
pattern =
"\""
+key+
"\""
;
int
key_pos =
StringFind
(text,pattern);
if
(key_pos<
0
)
return
(default_value);
int
colon_pos =
StringFind
(text,
":"
,key_pos);
if
(colon_pos<
0
)
return
(default_value);
int
start = colon_pos+
1
;
int
len   =
StringLen
(text);
int
end   = start;
//--- scan forward until a delimiter that can never appear inside a bare JSON number
while
(end<len)
     {
ushort
ch =
StringGetCharacter
(text,end);
if
(ch==',' || ch=='}' || ch=='\n' || ch=='\r' || ch==']')
